def test_partition():
    pred = lambda x: x % 2 == 0
    iterable = [1, 2, 3, 4, 5]
    false_iter, true_iter = partition(pred, iterable)
    assert list(false_iter) == [1, 3, 5]
    assert list(true_iter) == [2, 4]


